int parse_ccitt_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int processed = 0;
    int i;

    if (!p || !facilities || len <= 0) {
        return -1;
    }

    while (processed < len && p[processed] != 0x00) {
        switch ((p[processed] >> 6) & 0x03) {
        case 0x00:
            /* Unassigned - continue parsing */
            processed++;
            break;
        case 0x01:
            /* Type 1 - continue parsing */
            processed++;
            break;
        case 0x02:
            /* Type 2 - continue parsing */
            processed++;
            break;
        case 0x03:
            /* Type 3 - check for address and callsign */
            if (processed + 3 >= len) {
                return -1;
            }
            i = p[processed + 1];
            if (i > 0) {
                if (facilities->source_address)
                    memcpy(facilities->source_address, &p[processed + 2], i);
                if (i > 0 && i <= 6) {
                    memcpy(facilities->source_callsign, &p[processed + 2 + i], 7);
                }
            }
            i = p[processed + 1 + i + 1];
            if (i > 0) {
                if (facilities->dest_address)
                    memcpy(facilities->dest_address, &p[processed + 2 + i + 2], i);
                if (i > 0 && i <= 6) {
                    memcpy(facilities->dest_callsign, &p[processed + 2 + i + 2 + i], 7);
                }
            }
            processed += i + i + 4;
            break;
        }
    }

    if (p[processed] == 0x00) {
        return processed + 1;
    }

    return -1;
}

int parse_rose_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int bytes_processed = 0;
    unsigned char *end = p + len;
    unsigned char *q = p;

    while (q < end) {
        if (*q == 0x00) {
            break;
        }

        switch (*q >> 6) {
            case 0x00:
                q++;
                bytes_processed++;
                break;
            case 0x01:
                if (q + 1 >= end) {
                    return -1;
                }

                switch (*q >> 4 & 0x03) {
                    case 0x00:
                        facilities->source_address = *(q + 1);
                        break;
                    case 0x01:
                        facilities->dest_address = *(q + 1);
                        break;
                    default:
                        break;
                }

                q += 2;
                bytes_processed += 2;
                break;
            case 0x02:
                if (q + 2 >= end) {
                    return -1;
                }

                switch (*q >> 4 & 0x03) {
                    case 0x00:
                        facilities->source_call_length = *(q + 1);
                        if (facilities->source_call_length > 7) {
                            return -1;
                        }
                        memcpy(facilities->source_call, q + 2, facilities->source_call_length);
                        break;
                    case 0x01:
                        facilities->dest_call_length = *(q + 1);
                        if (facilities->dest_call_length > 7) {
                            return -1;
                        }
                        memcpy(facilities->dest_call, q + 2, facilities->dest_call_length);
                        break;
                    default:
                        break;
                }

                q += 3;
                bytes_processed += 3;
                break;
            default:
                return -1;
        }
    }

    return bytes_processed;
}

int parse_ccitt_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int processed = 0;

    while (processed < len) {
        unsigned char byte = p[processed];

        if (byte == 0x00) {
            break; // Termination byte encountered
        }

        unsigned char first_two_bits = (byte >> 6) & 0x03;

        switch (first_two_bits) {
            case 0x00:
                // Handle source address case
                if (processed + 1 >= len) {
                    return -1; // Invalid length
                }
                facilities->source_address = p[processed + 1];
                processed += 2;
                break;

            case 0x01:
                // Handle destination address case
                if (processed + 1 >= len) {
                    return -1; // Invalid length
                }
                facilities->dest_address = p[processed + 1];
                processed += 2;
                break;

            case 0x02:
                // Handle source call sign case
                if (processed + 1 >= len) {
                    return -1; // Invalid length
                }
                {
                    int call_len = p[processed + 1];
                    if (call_len >= 0 && call_len < sizeof(facilities->source_call)) {
                        memcpy(facilities->source_call, &p[processed + 2], call_len);
                        processed += 2 + call_len;
                    } else {
                        return -1; // Invalid call sign length
                    }
                }
                break;

            case 0x03:
                // Handle destination call sign case
                if (processed + 1 >= len) {
                    return -1; // Invalid length
                }
                {
                    int call_len = p[processed + 1];
                    if (call_len >= 0 && call_len < sizeof(facilities->dest_call)) {
                        memcpy(facilities->dest_call, &p[processed + 2], call_len);
                        processed += 2 + call_len;
                    } else {
                        return -1; // Invalid call sign length
                    }
                }
                break;

            default:
                return -1; // Invalid facility type
        }
    }

    return processed;
}

int parse_ccitt_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int processed = 0;
    unsigned char *end = p + len;

    while (p < end && *p != 0x00) {
        unsigned char byte = *p++;
        unsigned char type = (byte >> 6) & 0x03;

        switch (type) {
            case 0x00: // Reserved
                break;
            case 0x01: // Source address
                if (p + 1 > end)
                    return -1;
                facilities->source_address = *p++;
                break;
            case 0x02: // Destination address
                if (p + 1 > end)
                    return -1;
                facilities->dest_address = *p++;
                break;
            case 0x03: // Source or destination call sign
                if (p + 1 > end)
                    return -1;
                int call_len = *p++;
                if (call_len > ROSE_MAX_CALLSIGN_LEN || p + call_len > end)
                    return -1;
                memcpy(facilities->call_sign, p, call_len);
                p += call_len;
                break;
            default:
                return -1;
        }
        processed++;
    }

    if (p >= end && *p != 0x00)
        return -1;

    return processed;
}

int parse_ccitt_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int processed = 0;
    unsigned char *end = p + len;

    while (p < end) {
        unsigned char byte = *p++;

        if (byte == 0x00) {
            break;
        }

        processed++;

        switch ((byte >> 6) & 0x03) {
            case 0:
                // Handle case for address type
                if (p + 1 > end) {
                    return -1; // Invalid length
                }
                facilities->source_address = (p[0] << 8) | p[1];
                p += 2;
                processed += 2;
                break;
            case 1:
                // Handle case for destination call
                if (p + 1 > end) {
                    return -1;
                }
                facilities->dest_call_length = *p;
                p++;

                if (facilities->dest_call_length > ROSE_MAX_CPS) {
                    return -1;
                }

                if (p + facilities->dest_call_length > end) {
                    return -1;
                }
                memcpy(facilities->dest_call, p, facilities->dest_call_length);
                p += facilities->dest_call_length;
                processed += facilities->dest_call_length;
                break;
            case 2:
                // Handle case for source call
                if (p + 1 > end) {
                    return -1;
                }
                facilities->source_call_length = *p;
                p++;

                if (facilities->source_call_length > ROSE_MAX_CPS) {
                    return -1;
                }

                if (p + facilities->source_call_length > end) {
                    return -1;
                }
                memcpy(facilities->source_call, p, facilities->source_call_length);
                p += facilities->source_call_length;
                processed += facilities->source_call_length;
                break;
            case 3:
                // Termination
                return processed;
        }
    }

    return processed;
}
